// Rebuilds _ds_bundle.js and _ds_bundle.css from components/core/index.ts.
// Run: node scripts/build-bundle.js
import { buildSync } from 'esbuild';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dir = dirname(fileURLToPath(import.meta.url));
const ROOT  = join(__dir, '..');

const COMPONENTS = [
  'Accordion', 'ArrowLink', 'Badge', 'Breadcrumb', 'Button',
  'Checkbox', 'CheckboxGroup', 'FormField', 'Input', 'Logo',
  'MediaCard', 'Modal', 'NavigationBar', 'Radio', 'RadioGroup',
  'SectionHeader', 'Select', 'SocialLink', 'Stat', 'Tag',
  'Tabs', 'Textarea', 'Toast',
];

// Bundle to ESM in-memory; esbuild emits a sibling .css file automatically
// when CSS Module imports are present.
const result = buildSync({
  entryPoints: [join(ROOT, 'components/core/index.ts')],
  bundle: true,
  format: 'esm',
  platform: 'browser',
  target: ['es2020'],
  // React is loaded from CDN in consumer HTML pages — do not bundle it.
  external: ['react', 'react/jsx-runtime'],
  loader: {
    '.tsx': 'tsx',
    '.ts':  'ts',
    '.module.css': 'local-css',
  },
  jsxImportSource: 'react',
  outdir: ROOT,
  outExtension: { '.js': '._esm_tmp.js' },
  write: false,
  logLevel: 'warning',
});

const jsOut  = result.outputFiles.find(f => f.path.endsWith('._esm_tmp.js'));
const cssOut = result.outputFiles.find(f => f.path.endsWith('.css'));

if (!jsOut) throw new Error('esbuild produced no JS output');

// Convert the ESM named exports into window.TEDxAmsterdamDesignSystem assignments.
let esmCode = jsOut.text;
const exportMatch = esmCode.match(/^export\s*\{([^}]+)\}\s*;?\s*$/m);
const exportedNames = exportMatch
  ? exportMatch[1].split(',').map(s => s.trim().split(/\s+as\s+/).pop().trim())
  : COMPONENTS;
esmCode = esmCode.replace(/^export\s*\{[^}]+\}\s*;?\s*$/m, '');

const assigns = exportedNames.map(n => `  __ds_ns.${n} = typeof ${n} !== 'undefined' ? ${n} : undefined;`).join('\n');

const iife = [
  '// TEDxAmsterdam Design System — browser bundle',
  `// Components: ${COMPONENTS.join(', ')}`,
  '// Generated by scripts/build-bundle.js — do not edit manually.',
  '(function () {',
  "  'use strict';",
  "  var __ds_ns = window.TEDxAmsterdamDesignSystem = window.TEDxAmsterdamDesignSystem || {};",
  "  __ds_ns.__errors = [];",
  '',
  esmCode,
  '',
  assigns,
  '})();',
].join('\n');

writeFileSync(join(ROOT, '_ds_bundle.js'), iife, 'utf8');
console.log(`\u2713 _ds_bundle.js rebuilt — ${COMPONENTS.length} components`);

if (cssOut) {
  writeFileSync(join(ROOT, '_ds_bundle.css'), cssOut.text, 'utf8');
  console.log('\u2713 _ds_bundle.css rebuilt');
} else {
  writeFileSync(join(ROOT, '_ds_bundle.css'), '/* TEDxAmsterdam DS — component styles */\n', 'utf8');
  console.log('\u2713 _ds_bundle.css written (no component CSS yet)');
}
